import base64
import binascii
import re

with open('/tmp/suspicious_payloads.txt') as f:
    lines = [line.strip() for line in f if line.strip()]

def try_decodings(s):
    results = {}
    # Hex decode
    try:
        if len(s) % 2 == 0:
            decoded_hex = binascii.unhexlify(s)
            if b'FLAG{' in decoded_hex:
                results['hex'] = decoded_hex
    except Exception:
        pass
    # Base64 decode
    try:
        missing_padding = len(s) % 4
        padded_s = s + ('=' * (4 - missing_padding) if missing_padding != 0 else '')
        decoded_b64 = base64.b64decode(padded_s, validate=True)
        if b'FLAG{' in decoded_b64:
            results['base64'] = decoded_b64
    except Exception:
        pass
    # Check if ascii, has readable data
    try:
        astr = bytes.fromhex(s).decode('ascii')
        if 'FLAG{' in astr:
            results['ascii_hex'] = astr
    except Exception:
        pass
    return results

for line in lines:
    out = try_decodings(line)
    for enc, val in out.items():
        print(f'DECODE({enc}):', val)
    else:
        # Print some readable fields for further inspection
        if not out and re.search(r'[A-Za-z]{8,}', line):
            print('POSSIBLE STRING:', line)
